package icon

import (
	"context"
	"io"

	"github.com/a-h/templ"
)

// FolderFilled supplies solid counterparts to the folder picker and role icons.
// These paths follow the existing Lucide symbols' 24px geometry. Interior details
// are transparent cutouts, so they remain legible on any theme background.
func FolderFilled(name string) templ.Component {
	path, ok := filledFolderPaths[name]
	if !ok {
		name = "folder"
		path = filledFolderPaths[name]
	}
	return templ.ComponentFunc(func(_ context.Context, w io.Writer) error {
		_, err := io.WriteString(w, `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="currentColor" class="size-4" data-folder-filled-symbol="`+name+`" aria-hidden="true" focusable="false"><path fill-rule="evenodd" d="`+path+`"/></svg>`)
		return err
	})
}

